COMMENT ON COLUMN "rbac_policy_revision_counters"."last_revision" IS '最近已分配的 RBAC policy revision';
-- Create "rbac_policy_revisions" table
CREATE TABLE "rbac_policy_revisions" (
  "revision" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "reason" character varying NOT NULL,
  "role_id" uuid NULL,
  "user_id" uuid NULL,
  "permission_id" uuid NULL,
  "created_at" bigint NOT NULL,
  PRIMARY KEY ("revision")
);
-- Set comment to column: "revision" on table: "rbac_policy_revisions"
COMMENT ON COLUMN "rbac_policy_revisions"."revision" IS '单调递增的 RBAC policy revision';
-- Set comment to column: "reason" on table: "rbac_policy_revisions"
COMMENT ON COLUMN "rbac_policy_revisions"."reason" IS '触发 policy 变更的稳定原因';
-- Set comment to column: "role_id" on table: "rbac_policy_revisions"
COMMENT ON COLUMN "rbac_policy_revisions"."role_id" IS '相关外部角色ID';
-- Set comment to column: "user_id" on table: "rbac_policy_revisions"
COMMENT ON COLUMN "rbac_policy_revisions"."user_id" IS '相关外部用户ID';
-- Set comment to column: "permission_id" on table: "rbac_policy_revisions"
COMMENT ON COLUMN "rbac_policy_revisions"."permission_id" IS '相关外部权限ID';
-- Set comment to column: "created_at" on table: "rbac_policy_revisions"
COMMENT ON COLUMN "rbac_policy_revisions"."created_at" IS '创建时间戳毫秒';
-- Create "role_permissions" table
